180: * its rounding date is before the sheet's policy date (the sheet's today when blank), half to even on or after it.
181: */
182:export function roundingOf(claim: Claim, session: Session): Rounding {
183:  const mode = session.settingOn('rounding', claim.date);
184:  if (mode === 'half-up' || mode === 'half-even') return mode;
185:  const policy = session.policyDate() || session.today();
186:  return policy !== null && claim.roundingDate < policy ? 'half-up' : 'half-even';
187:}
188:
189:/**
190: * The due fixed when the claim was settled, else the greater of the floor in force on its date and its figure (the one
191: * its person's last statement bound it to, else its amount times the rate of its person's grade on its date, both in
192: * force on its date, or n/a with no rate) with its late charge added on top. A correction has neither floor nor late
193: * charge.
194: */
195:export function claimDue(claim: Claim, rates: Rate[], grades: PersonGrade[], session: Session): string {
196:  if (claim.settledDue !== null) return claim.settledDue;
197:  const grade = gradeOn(grades, claim.date);
198:  const due = dueOf(claim.amount, grade === undefined ? undefined : rateOn(rates, grade, claim.date, claim.rateStamp), roundingOf(claim, session));
199:  const figure = bound(claim) ? (claim.statedDue ?? 'n/a') : due;
200:  if (figure === 'n/a' || isCorrection(claim)) return figure;
201:  return floored(sumDues([figure, lateCharge(claim, figure, grades, session)]), session.settingOn('floor', claim.date));
202:}
203:
204:/**
205: * The day the claim goes overdue after, and its late charge counts from: its due-by plus the grace days of its person's
206: * grade on its date in force on that date, else its due-by. The due-by shown stays as it is.
207: */
208:export function overdueBy(claim: Claim, grades: PersonGrade[], session: Session): string {
209:  if (claim.dueBy === '') return claim.dueBy;
210:  const grade = gradeOn(grades, claim.date);
211:  const grace = grade === undefined ? null : session.settingOn('grace-' + grade, claim.date);
212:  return grace === null || grace === '' ? claim.dueBy : plusDays(claim.dueBy, Number(grace));
213:}
214:
215:/**
216: * For every full 30 days an OPEN claim is past its due-by (plus its grace) on the sheet's today, the late percent in
217: * force on that boundary (the due-by plus its grace plus 30, 60, 90 ... days) of the figure plus the charges of the
218: * boundaries before it (compounding), each rounded like the claim's due, added up; 0.00 when it is not overdue, and on a correction.
219: */
220:export function lateCharge(claim: Claim, figure: string, grades: PersonGrade[], session: Session): string {
221:  const by = overdueBy(claim, grades, session);
222:  const today = session.today();
223:  if (!isOpen(claim) || isCorrection(claim) || by === '' || today === null) return '0.00';
224:  if (deferred(claim, today)) return '0.00';
225:  const days = Math.round((Date.parse(today) - Date.parse(by)) / 86_400_000);
226:  const charges: string[] = [];
227:  for (let boundary = 1; boundary <= Math.floor(days / 30); boundary++) {
228:    const pct = session.settingOn('late-pct', plusDays(by, 30 * boundary));
229:    if (pct !== null) charges.push(percentOf(sumDues([figure, ...charges]), pct, 1, roundingOf(claim, session)));
230:  }
231:  return sumDues(charges);
232:}
233:
234:/** The yyyy-mm-dd date the days after the date. */
235:export function plusDays(date: string, days: number): string {
236:  return new Date(Date.parse(date) + days * 86_400_000).toISOString().slice(0, 10);
237:}
238:
239:/** Whether the claim's due is fixed, by settling or by a statement, rather than worked out from the rates. */
240:export function dueFixed(claim: Claim): boolean {
241:  return claim.settledDue !== null || (bound(claim) && claim.statedDue !== null);
242:}
243:
244:/** Whether the claim is OPEN or PENDING, not deferred, and its due-by plus its grace is before the sheet's today. */
245:export function overdue(claim: Claim, grades: PersonGrade[], session: Session): boolean {
246:  const today = session.today();
247:  return isOpen(claim) && today !== null && overdueBy(claim, grades, session) < today && !deferred(claim, today);
248:}
