250:type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle' | 'delete' | 'restore' | 'review';
251:
252:/** Sums amounts with two decimals exactly, in whole cents. */
253:export function sumAmounts(amounts: string[]): string {
254:  const cents = amounts.reduce((total, a) => total + Math.round(Number(a) * 100), 0);
255:  return (cents / 100).toFixed(2);
256:}
